/* Reviewed presentation copy. Calculations, source records and form values stay intact. */
(()=>{'use strict';
const catalog=[["Een bekende gridpositie én positie na ronde één zijn nodig. Pitstraatstarts en onzekere metingen tellen niet als bruikbaar; bekende niet-starts tellen niet in de noemer.","A known grid position and lap-one position are required. Pit-lane starts and uncertain measurements are not usable; known non-starts are excluded from the denominator.","We hebben de startpositie én de positie na ronde één nodig. Starts vanuit de pitstraat en onzekere metingen tellen niet mee. Wie niet startte, telt ook niet mee in het totaal.","We need both the grid position and the position after lap one. Pit-lane starts and uncertain measurements are excluded. Drivers who did not start are also excluded from the total."],["Positief = gewonnen, negatief = verloren. Dit beschrijft startuitkomsten; startpositie en uitval van anderen zijn niet afzonderlijk gecorrigeerd.","Positive = gained, negative = lost. This describes start outcomes; grid position and other drivers’ retirements are not separately adjusted.","Boven nul betekent plaatsen gewonnen; onder nul betekent plaatsen verloren. Ook uitval van anderen kan daarbij helpen.","Above zero means places gained; below zero means places lost. Other drivers retiring can also contribute."],["Alle cijfers gebruiken uitsluitend de gemeten starts van deze coureur in de gekozen periode. Ontbrekende metingen worden niet als positiebehoud geteld. De witte curve en grijze modelband beschrijven de trend per gridpositie; onderbroken delen hebben weinig of geen eigen starts.","All figures use only this driver’s measured starts within the selected period. Missing observations do not count as positions held. The white curve and grey model band describe the trend by grid position; dashed sections have few or no own starts.","Alleen bruikbare starts tellen mee. Ontbrekende metingen gelden niet als een behouden positie. De witte lijn vat het verloop samen; bij stippellijnen zijn weinig of geen starts gemeten.","Only usable starts count. Missing measurements do not count as a position held. The white line summarizes the pattern; dashed parts have few or no measured starts."],["50 = gelijkwaardig aan de referentie. Hoger = vaker een betere uitkomst vanaf dezelfde gridpositie, op hetzelfde circuit en bij dezelfde veldgrootte. Deze score is al gecorrigeerd voor startpositie.","50 = on a par with the reference. Higher = more often a better outcome from the same grid position, at the same circuit and field size. This score already adjusts for starting position.","50 betekent ongeveer gelijk aan andere rijders vanaf dezelfde startplek, op hetzelfde circuit en in een even groot veld. Hoger betekent vaker een gunstiger resultaat.","50 means roughly level with other drivers from the same grid position, at the same circuit and with the same field size. Higher means a better result more often."],["Eerste van twee opeenvolgende gridposities waar de modelcurve minstens 0,5 positie winst aangeeft. Dit is een ruwe positiegrens, zonder kanscorrectie; de grijze band laat zien hoe onzeker deze vorm is.","First of two consecutive grid positions where the model curve indicates at least 0.5 positions gained. This is a raw position threshold without opportunity adjustment; the grey band shows uncertainty about this shape.","De eerste van twee opeenvolgende startplekken waar de lijn minstens een halve plaats winst aangeeft. Dit is een geschatte grens; weinig gegevens maken de grens onzeker.","The first of two consecutive starting positions where the line shows at least half a place gained. This boundary is an estimate; limited data make it uncertain."],["De doorgetrokken modelcurve gebruikt ook dun bezette posities; de onderbroken stukken zijn modelinschattingen. De gecorrigeerde scores gebruiken alleen echte vergelijkbare starts en gelden voor hun vermelde dekking; vergelijk rijders op gezamenlijke onderbouwde startposities en dezelfde contexten. Auto, weer, starttype en incidenten zijn niet geïsoleerd. Uitval vóór de eerste gemeten doorkomst ontbreekt. Dit is startresultaat, geen zuivere vaardigheidsscore.","The full model curve also uses sparse positions; dashed segments are model estimates. Adjusted scores use only actual matched starts and apply to their stated coverage; compare drivers over shared supported grid positions and the same contexts. Car, weather, start type and incidents are not isolated. Retirements before the first measured lap ending are absent. This describes start outcomes, not pure driver skill.","De lijn vat de gemeten starts samen. Stippellijnen zijn schattingen bij weinig gegevens. De vergelijkingsscores gebruiken alleen passende starts. Auto, weer en incidenten kunnen het resultaat beïnvloeden. Zonder een gemeten positie na ronde één ontbreekt die start. Dit is dus geen los rapportcijfer voor rijvaardigheid.","The line summarizes measured starts. Dashed parts are estimates where data are limited. Comparison scores use suitable starts only. Car, weather and incidents can affect the result. Starts without a measured lap-one position are missing. This is therefore not a standalone driver-skill rating."],["Boven nul is positiewinst, onder nul verlies. Violins en kwartielen tonen de spreiding; de witte curve toont de trend met een grijze 95%-modelband. Elk punt is één race.","Above zero is gain, below zero loss. Violins and quartiles show the distribution; the white curve shows the trend with a grey 95% model band. Each point is one race.","Ieder punt is één race. Boven nul: plaatsen gewonnen. Onder nul: plaatsen verloren. De paarse vorm laat zien welke uitkomsten vaak voorkomen. De witte lijn vat het verloop samen; de grijze band laat de onzekerheid rond die lijn zien.","Each dot is one race. Above zero: places gained. Below zero: places lost. The purple shape shows which results are common. The white line summarizes the pattern; the grey band shows uncertainty around that line."],["Vaste, niet-lineaire schaal van −10 tot +10 posities: 0, 1, 3, 6 en 10 staan aan beide kanten van nul op gelijke visuele afstand. Kleine streepjes tonen de overige hele posities. Boven nul is beter; onder nul slechter. De as en pijlen blijven staan bij horizontaal scrollen.","Fixed non-linear scale from −10 to +10 positions: 0, 1, 3, 6 and 10 are equally spaced on either side of zero. Small ticks show the other whole positions. Above zero is better; below zero is worse. The axis and arrows stay fixed during horizontal scrolling.","De as geeft kleine verschillen rond nul meer ruimte en loopt van 10 plaatsen verlies tot 10 plaatsen winst. De streepjes zijn hele plaatsen. De as blijft staan als je zijwaarts scrolt.","The axis gives small changes near zero more space and runs from 10 places lost to 10 gained. Tick marks are whole places. The axis stays fixed when you scroll sideways."],["Ook de curve, violins en modelband worden bij de asgrens afgekapt; hun onderliggende waarden blijven behouden.","The curve, violins and model band are also clipped at the axis boundary; their underlying values are retained.","Een lijn of vorm kan de rand bereiken. De volledige waarden blijven wel in de berekening staan.","A line or shape can reach the edge. Its full values remain in the calculation."],["Hoeveel posities won of verloor deze rijder bij zijn eerste doorkomst na één ronde, per startpositie? Iedere kolom verzamelt zijn races vanaf die startpositie. Alle gridposities staan op de x-as; zonder gemeten starts blijft de kolom leeg.","How many positions did this driver gain or lose at their first lap ending, by starting grid position? Each column collects their races from that starting position. Every grid position appears on the x-axis; positions without measured starts have empty columns.","Hoeveel plaatsen won of verloor deze rijder in ronde één? Elke kolom bevat de races vanaf één startplek. Een lege kolom betekent dat er geen bruikbare starts zijn gemeten.","How many places did this driver gain or lose on lap one? Each column contains races from one starting position. An empty column means no usable starts were measured."],["De geselecteerde periode geldt ook voor starts. Boven nul is positiewinst, onder nul verlies; nul betekent positie behouden.","The selected period also applies to starts. Above zero is gain, below zero loss; zero means position held.","Dit overzicht gebruikt alle beschikbare starts uit de loopbaan. Boven nul: plaatsen gewonnen. Onder nul: plaatsen verloren. Nul: dezelfde positie.","This overview uses all available career starts. Above zero: places gained. Below zero: places lost. Zero: position held."],["Boven de cyaanlijn: sneller · onder de cyaanlijn: langzamer · op nul: even snel. Iedere stip is één racemediaan.","Above cyan: faster · below cyan: slower · zero: equal pace. Each point is one race median.","Boven de blauwe lijn: sneller. Onder de lijn: langzamer. Op nul: even snel. Iedere stip vat één race samen.","Above the blue line: faster. Below it: slower. At zero: equal pace. Each dot summarizes one race."],["P1 bovenaan. Niet-lineaire positie-as met uitsluitend gehele posities. Elke stip is één kwalificatie; paars toont de verdeling en kwartielen, wit de mediaan.","P1 is at the top. Nonlinear position axis with integer positions only. Each dot is one qualifying result; purple shows the distribution and quartiles, white the median.","De beste uitslagen staan bovenaan. Elke stip is één kwalificatie. De paarse vorm laat zien waar de uitslagen samenkomen; de witte streep ligt in het midden van de resultaten.","The best results are at the top. Each dot is one qualifying session. The purple shape shows where results gather; the white bar marks their middle value."],["Nul seconden bovenaan. ln(1 + tijdsverschil in seconden); aslabels en hovers tonen de oorspronkelijke seconden. Alleen dezelfde kwalificatiefase als de pole-tijd.","Zero seconds is at the top. ln(1 + gap in seconds); axis labels and tooltips show original seconds. Only the same qualifying phase as the pole time.","Bovenaan staat nul: even snel als de pole-tijd. Kleine tijdsverschillen krijgen meer ruimte. De as en de punten tonen seconden.","Zero at the top means matching the pole time. Small time gaps get more space. Axis labels and dots show seconds."],["Indicatieve puntgewijze 95%-bootstrapband van de vloeiende best-fittrend","Indicative pointwise 95% bootstrap band of the smooth best-fit trend","Onzekerheidsmarge rond de vloeiende lijn (95%). De fout in geschatte kwalificatietijden zit hier niet volledig in.","Uncertainty around the smooth line (95%). Error in estimated qualifying times is not fully included."],["Eén punt per kwalificatie, gegroepeerd per jaar. Beste resultaten bovenaan. Beide grafieken delen dezelfde jaarposities en één horizontale scrollbar; assen blijven staan.","One point per qualifying session, grouped by year. Best results at the top. Both plots share year positions and one horizontal scrollbar; axes remain fixed.","Elke stip is één kwalificatie, bij het bijbehorende jaar. Beste resultaten bovenaan. Scroll zijwaarts om beide grafieken samen te bekijken.","Each dot is one qualifying session in its year. Best results are at the top. Scroll sideways to move both charts together."],["Open ruitjes zijn schattingen. De violins, medianen en curves gebruiken alle waarden. n telt het totaal; ≈ geeft aan hoeveel daarvan geschat zijn.","Hollow diamonds are estimates. Violins, medians and curves use all values. n is the total; ≈ shows how many are estimated.","Open ruitjes zijn geschatte tijden. Ze tellen mee in de verdelingen en lijnen. n is het aantal resultaten; ≈ geeft het aantal schattingen aan.","Hollow diamonds are estimated times. They count in the shapes and lines. n is the number of results; ≈ shows how many are estimates."],["Schaduwzones: gebruikelijke Q1/Q2/Q3-positiegrenzen per seizoen; afzonderlijke sessies kunnen afwijken.","Shading: usual Q1/Q2/Q3 rank cutoffs by season; individual sessions may differ.","De achtergrondkleuren tonen de gebruikelijke plaatsen voor Q1, Q2 en Q3 in dat seizoen. Het kan per kwalificatie anders zijn.","Background colours show the usual Q1, Q2 and Q3 positions for that season. Individual qualifying sessions may differ."],["Onvoldoende gedeelde metingen voor deze veldvergelijking. Ontbrekend is geen nul.","Insufficient shared measurements for this field comparison. Missing does not mean zero.","Er zijn te weinig vergelijkbare metingen om dit overzicht te tonen. Een ontbrekende meting betekent niet nul.","There are too few comparable measurements to show this view. A missing measurement does not mean zero."],["Iedere schone ronde in vrije lucht is één datapunt, voor alle coureurs die in dezelfde races meededen. De viool, kwartielen en mediaan gebruiken alle individuele ronderangen samen. Lager is sneller in het gemeten veld.","Every clean lap in clear air is one data point for every driver who took part in the same races. The violin, quartiles and median use all individual lap ranks pooled together. Lower is faster within the measured field.","Elke bruikbare ronde is één punt. We vergelijken rijders die aan dezelfde races meededen. Een lager plaatsnummer betekent een snellere ronde ten opzichte van het gemeten veld.","Each usable lap is one data point. We compare drivers who entered the same races. A lower rank means a faster lap relative to the measured field."],["Afwijking van de veldmediaan in dezelfde race en op dezelfde compound. Per coureur en compound telt de mediaan één keer; de veldreferentie vereist minstens drie coureurs. Daarna krijgt iedere race één waarde.","Difference from the field median in the same race on the same compound. Each driver and compound contributes one median; the field reference requires at least three drivers. Each race then contributes one value.","We vergelijken met het midden van het gemeten veld, in dezelfde race en op hetzelfde bandentype. Daarvoor zijn minstens drie rijders nodig. Iedere rijder krijgt daarna één waarde per race.","We compare against the middle of the measured field, in the same race and on the same tyre type. At least three drivers are needed. Each driver then gets one value per race."],["Alle geschikte ronden tellen mee. Langere races leveren meer waarnemingen; de dekking vermeldt ook het aantal races.","Every eligible lap counts. Longer races contribute more observations; coverage also reports the number of races.","Alle bruikbare ronden tellen mee. Lange races leveren daardoor meer meetpunten. Het aantal races staat er ook bij.","All usable laps count. Longer races therefore contribute more points. The number of races is also shown."],["De auto, het verkeer en de omstandigheden zijn niet volledig geïsoleerd; dit is geen algemeen rapportcijfer voor de coureur.","Car, traffic and conditions are not fully isolated; this is not an overall driver rating.","Ook de auto, het verkeer en de omstandigheden spelen mee. Dit getal beoordeelt de rijder dus niet in zijn eentje.","The car, traffic and conditions also matter. This number therefore does not assess the driver alone."],["Viool: verdeling van alle meetpunten · dikke lijn: 25%–75% · wit: mediaan. Bij de metronoom telt iedere ronde; bij pitvensters en opwarming iedere bruikbare race. Coureurs zonder bruikbare metingen worden bij de metronoom niet getoond. Alleen waargenomen races van de gekozen coureur vormen de referentie.","Violin: distribution of all observations · thick line: 25%–75% · white: median. The metronome uses every lap; pit windows and warm-up use every usable race. Drivers without usable observations are hidden in the metronome. Only observed races of the selected driver define the reference.","De gekleurde vorm toont de verdeling. De dikke lijn bevat de middelste helft; wit markeert de middelste waarde. De metronoom gebruikt iedere bruikbare ronde. Rijders zonder metingen staan niet in die lijst. We gebruiken de races van de gekozen rijder.","The coloured shape shows the spread. The thick line contains the middle half; white marks the middle value. The metronome uses every usable lap. Drivers without measurements are hidden from that list. We use the selected driver’s races."],["Elk punt is de mediane tijdwinst van de gekozen meetvensters binnen één race. De witte streep en het middelste 50%-bereik vatten de races van dat seizoen samen; elke bruikbare race telt eenmaal. De viool toont de spreiding vanaf vijf races. Dit zijn seconden per gemeten race, geen opgetelde seizoenwinst en geen onzekerheidsinterval.","Each point is one race’s median time gain across the selected measurement windows. The white line and middle 50% range summarize that season’s races; each usable race counts once. A violin shows the distribution from five races. These are seconds per measured race, not summed season gains or a confidence interval.","Elke stip vat de tijdwinst binnen één race samen. De witte streep staat in het midden van de race-uitkomsten van dat jaar; paars toont de middelste helft. Vanaf vijf races toont de gekleurde vorm ook de verdeling. De seconden zijn niet bij elkaar opgeteld.","Each dot summarizes time gained in one race. The white bar marks the middle of that year’s race results; purple shows the middle half. From five races, the coloured shape also shows the spread. Seconds are not added together."],["Y-as: symmetrisch logaritmisch in seconden, met extra ruimte rond nul. Witte curve: Gaussische best-fittrend · grijze band: 95%-marge van de trend · witte strepen: jaarmedianen · violen: gemeten spreiding.","Y-axis: symmetric logarithmic seconds, with extra room around zero. White curve: Gaussian best-fit trend · grey band: 95% trend interval · white bars: annual medians · violins: measured spread.","Rond nul krijgen kleine verschillen meer ruimte. De as toont nog steeds seconden. Witte lijn: verloop door de jaren. Grijze band: onzekerheid rond die lijn (95%). Witte strepen: het midden per jaar. Gekleurde vormen: de spreiding.","Small differences near zero get more space. The axis still shows seconds. White line: the pattern over time. Grey band: uncertainty around that line (95%). White bars: the middle value for each year. Coloured shapes: the spread."],["Elke gelijkgenummerde stop van beide rijders vormt één afgerond venster. Alleen bij evenveel totale stops; vensters met andere stops worden geweigerd. Neutralisaties buiten het venster maken een eerdere cyclus niet ongeldig. Dit meet ook tempo en verkeer tijdens de cyclus.","Each same-numbered stop pair forms one completed window. Equal total stop counts are required; windows containing other stops are rejected. Neutralisations outside the window do not invalidate an earlier cycle. This also measures pace and traffic during the cycle.","We vergelijken de eerste stops met elkaar, daarna de tweede, enzovoort. Beide rijders moeten even vaak zijn gestopt. Een extra stop binnen dezelfde vergelijking maakt die onbruikbaar. Ook racetempo en verkeer tellen mee in de gemeten tijdwinst.","We compare the first stops, then the second stops, and so on. Both drivers must have stopped equally often. Another stop within the comparison makes it unusable. Race pace and traffic also contribute to measured time gained."],["Van de ronde vóór de eerste stop van het paar tot één ronde na hun laatste stop. Dit is de gemeten uitkomst van het hele tussenliggende raceverloop, inclusief tempo en verkeer.","From the lap before the pair’s first stop to one lap after their last stop. This measures the entire intervening race sequence, including pace and traffic.","We meten vanaf de ronde vóór hun eerste stop tot één ronde na hun laatste stop. Alles daartussen telt mee, dus ook racetempo en verkeer.","We measure from the lap before their first stop to one lap after their last stop. Everything in between counts, including race pace and traffic."],["Alleen de eigen in- en uitronde. De tegenstander hoeft nog niet gestopt te hebben; het normale pitverlies is hierin zichtbaar. Gebruik het afgeronde pitprogramma voor de gezamenlijke uitkomst.","Only the selected driver’s in- and out-lap. The opponent may not have stopped yet, so normal pit loss is visible here. Use the completed pit programme for the joint outcome.","Hier meten we alleen de ronde waarin deze rijder binnenkomt en de ronde waarin hij weer vertrekt. De tegenstander kan nog moeten stoppen. Kies het volledige stopverloop om hun gezamenlijke uitkomst te bekijken.","Here we measure only the lap when this driver enters the pits and the lap when he leaves. The opponent may still need to stop. Choose the full stop sequence to see their combined outcome."],["In het seizoenoverzicht is ieder punt één race; klik om de bronvergelijkingen te openen. In de verdieping is ieder punt één tegenstander of stopcyclus in dezelfde race. Klik voor tijdsverschillen, stopronden en posities. Een viool verschijnt vanaf vijf tegenstanders met minstens twee verschillende uitkomsten. De viool toont spreiding, geen betrouwbaarheidsinterval.","In the season overview each point is one race; click to open source comparisons. In the detail each point represents one opponent or stop cycle in the same race. Click for time gaps, stop laps and positions. A violin appears from five opponents with at least two distinct outcomes. The violin shows spread, not a confidence interval.","Bovenaan is elke stip één race. Klik om de vergelijkingen uit die race te openen. Daar staat elke stip voor één tegenstander of één stopvergelijking. De gekleurde vorm toont hoe de uitkomsten verspreid zijn, niet hoe zeker de lijn is.","In the season chart, each dot is one race. Click to open its comparisons. There, each dot is one opponent or one stop comparison. The coloured shape shows how results are spread, not how certain the line is."],["De neutralisatiecontext is niet volledig bevestigd. Geen geregistreerde SC/VSC betekent hier niet bewezen groen.","Neutralisation context is not fully confirmed. No recorded SC/VSC does not prove green conditions here.","Niet voor dit hele meetvenster is bekend of er een safetycar was. Geen geregistreerde safetycar betekent daarom niet zeker vrij racen.","Safety-car information is incomplete for this measurement window. No recorded safety car therefore does not guarantee normal racing throughout."],["Waargenomen tijd- en positieverloop; geen bewezen effect van uitsluitend de stopstrategie.","Observed time and position changes; not a proven effect of stop strategy alone.","Dit is de gemeten verandering in tijd en positie. Daaruit blijkt niet welk deel door de stopstrategie kwam.","This is the measured change in time and position. It does not show how much was caused by the pit strategy."],["Iedere waarde gebruikt de eigen loopbaan van de coureur in de vaste bronperiode. Een andere coureur toevoegen verandert deze waarden niet. De periode en raceset bovenaan gelden voor de aanvullende contextvergelijking hieronder; deze vaste waarden blijven bij hun eigen bronperiode.","Each value uses the driver’s own career within the fixed source period. Adding another driver does not change these values. The period and race cohort above apply to the additional contextual comparison below; these fixed values retain their own source period.","Deze cijfers gebruiken de volledige beschikbare loopbaan per rijder. Een andere rijder toevoegen verandert ze niet. De periode en racekeuze bovenaan gelden voor de extra vergelijking verderop. Beschikbare bronjaren:","These figures use each driver’s full available career. Adding another driver does not change them. The period and race selection above apply to the additional comparison further down. Available source years:"],["Een streep is geen nul. Scores rond 50 zijn gelijkwaardig aan hun referentie; een hoger veldpercentiel betekent een gunstigere ronderang. Negatief teamgenoot- of vrije-baantempo betekent sneller. Positieve pitwinst betekent tijd gewonnen. De winstgrenzen zijn verkennende modeluitkomsten, geen universele kwaliteitsgrenzen.","A dash is not zero. Scores near 50 are level with their reference; a higher field percentile means a better lap rank. Negative teammate or clear-air pace means faster. Positive pit gain means time gained. Gain boundaries are exploratory model outcomes, not universal skill thresholds.","Een streep betekent onbekend. Bij de start- en racescore is 50 ongeveer gelijk aan de passende vergelijking. Bij de veldscore is hoger gunstiger. Een negatief tempoverschil betekent sneller; een positieve pitbalans betekent tijd gewonnen. De geschatte winstgrens is geen grens tussen goede en slechte rijders.","A dash means unknown. A start or race score of 50 is roughly level with the matched comparison. Higher field scores are better. A negative pace difference means faster; positive pit balance means time gained. The estimated gain boundary does not separate good drivers from bad ones."],["De exacte eerder opgeslagen fits en modelbanden, zonder nieuwe berekening of invloed van de selectie. Gedeelde assen maken de curves vergelijkbaar. Geen lijn over ontbrekende meetreeksen. De start- en racecurves gebruiken de niet-lineaire positieschaal; afstand tot pole blijft op de logaritmische 0–4-secondenschaal. De pitbalans gebruikt dezelfde symmetrisch logaritmische secondenas als het coureursprofiel. Ruwe waarden blijven in de bronbestanden bewaard.","Exact previously archived fits and model bands, without refitting or selection influence. Shared axes make the curves comparable. Missing measured runs are not bridged. Start and race curves use the nonlinear position scale; pole gap retains the logarithmic 0–4-second scale. Pit balance uses the same symmetric logarithmic seconds axis as the driver profile. Raw values remain in the source files.","Dit zijn de bewaarde lijnen van iedere rijder, zonder nieuwe berekening. De assen zijn gelijk, zodat je de lijnen kunt vergelijken. De vorm van de as is dezelfde als bij het coureursprofiel. Auto’s, tegenstanders en omstandigheden kunnen wel verschillen.","These are each driver’s saved curves, without recalculation. Shared axes let you compare the lines. Axis shapes match the driver profile. Cars, opponents and conditions may still differ."],["Bewaarde schone ronden in vrije lucht, met race, seizoen, circuitvariant, rondenummer, compound, veldgrootte en ronderang. Werkelijke rondetijden zijn alleen toegevoegd waar de bewaarde millisecondeklok beschikbaar is. Ontbrekende tijden blijven onbekend.","Retained clean clear-air laps, with race, season, layout, lap number, compound, field size and lap rank. Actual lap times are included only where a retained millisecond clock is available. Missing times remain unknown.","Hier bewaren we bruikbare ronden zonder hinder van voorliggers, per circuitvariant en jaar. Ook bandentype, rondenummer en tegenstanders blijven bekend. Een ontbrekende rondetijd wordt niet geschat.","We retain usable laps without traffic ahead, by circuit layout and year. Tyre type, lap number and opponents are retained too. A missing lap time is not estimated."],["Losse rondetijden uit andere seizoenen of auto’s vormen geen eerlijke snelheidsranglijst. Circuitvarianten blijven apart; de opgeslagen race- en rondecontext maakt latere passende vergelijkingen mogelijk.","Raw lap times from different seasons or cars do not form a fair speed ranking. Layouts remain separate; the retained race and lap context enables suitable later comparisons.","Vergelijk losse rondetijden uit verschillende jaren of auto’s voorzichtig. Een sneller getal bewijst dan geen betere rijder. We houden circuitvarianten en racegegevens apart voor passende vergelijkingen.","Treat lap times from different years or cars with care. A faster number does not then prove a better driver. Circuit layouts and race details are kept separate for suitable comparisons."],["Geen voldoende onderbouwde gezamenlijke vergelijking in deze selectie. Verbreed de periode of kies een andere eigenschap; ontbrekende waarnemingen krijgen geen nulscore.","No sufficiently supported common comparison in this selection. Expand the period or choose another measure; missing observations are not assigned zero.","Er zijn te weinig passende metingen om deze rijders hier te vergelijken. Kies een ruimere periode of een andere eigenschap. Ontbrekende metingen krijgen geen nul.","There are too few suitable measurements to compare these drivers here. Choose a wider period or another trait. Missing measurements do not receive zero."],["Iedere gedeelde context telt voor alle geselecteerde coureurs even zwaar. Een context vereist per coureur minstens twee verschillende races. Bij start en racevervolg gebruiken we het voordeel boven de referentie zonder eigen bijdrage. Er wordt niet naar ontbrekende context geëxtrapoleerd.","Each shared context has the same weight for every selected driver. Each driver must have at least two different races in a context. Starts and race progression use advantage over a reference excluding the focal driver. No extrapolation to missing contexts.","We vergelijken alleen situaties die bij alle gekozen rijders voorkomen, met minstens twee races per rijder. Elke soort situatie telt even zwaar. Bij starts en racevervolg vergelijken we met andere rijders; de eigen rijder telt niet mee in die vergelijking.","We compare only situations found for every selected driver, with at least two races per driver. Each type of situation has equal weight. Starts and race progression are compared with other drivers; the driver being assessed is left out of that reference."],["De getoonde mediaan beschrijft de werkelijk gemeten prestaties binnen de gekozen raceset. Dat is nog geen geïsoleerde kwaliteit of eerlijke vergelijking over tijdperken. Bij ronderangen telt iedere bruikbare ronde; de onzekerheid bemonstert complete races.","The median describes each driver’s measured performance within the selected race cohort. It is not isolated skill or a fair era comparison. Lap ranks use every eligible lap; uncertainty resamples complete races.","Dit getal vat de gemeten resultaten in de gekozen races samen. Het laat de rijder niet los zien van zijn auto en omstandigheden. Bij rondetijden telt iedere bruikbare ronde mee. De onzekerheid houdt rekening met meerdere ronden uit dezelfde race.","This number summarizes measured results in the selected races. It does not separate the driver from the car and conditions. Every usable lap counts for lap-time ranks. Uncertainty accounts for multiple laps from the same race."],["Alleen races waaraan alle gekozen coureurs deelnamen. In het veldoverzicht tellen ook andere deelnemers aan diezelfde races mee. Bruikbare metingen kunnen per rijder alsnog verschillen.","Only races entered by every selected driver. The field overview also includes other participants in those same races. Eligible observations may still differ by driver.","Hier tellen alleen races mee waaraan alle gekozen rijders deelnamen. Een rijder kan in die races toch minder bruikbare metingen hebben.","Only races entered by all selected drivers count here. A driver may still have fewer usable measurements in those races."],["Eigen carrièrekansen: iedere rijder gebruikt zijn eigen gereden races in de periode. Dit is een loopbaanbeschrijving, geen vergelijking bij gelijke raceblootstelling.","Own career opportunities: each driver uses their own races within the period. This describes careers, not equal race exposure.","Elke rijder gebruikt zijn eigen races uit de gekozen periode. Hun kalenders, aantallen races en omstandigheden kunnen verschillen.","Each driver uses their own races in the selected period. Their calendars, race counts and conditions can differ."],["De vaste context bevat circuitvariant, veldgrootte, periode en beginpositie of relevante compound/racefase. Onbekend weer en autocondities zijn niet volledig gelijkgesteld. De marges gebruiken gedeelde positieve bootstrapgewichten per race, ook voor de referentieraces. Ze zijn conditioneel op deze waargenomen contexten en corrigeren niet voor onbekende auto- of weersinvloed.","Fixed contexts contain circuit layout, field size, period and origin position or relevant compound/race phase. Unknown weather and car conditions are not fully controlled. Intervals use shared positive race-bootstrap weights, including reference races. They are conditional on the observed contexts and do not remove unknown car or weather effects.","We houden rekening met onder meer circuit, beginpositie, veldgrootte en periode. Verschillen in auto en weer kunnen blijven meespelen. De marge laat onzekerheid in deze vergelijking zien; zij neemt niet alle onbekende invloeden weg.","We account for factors including circuit, starting position, field size and period. Car and weather differences can still matter. The interval shows uncertainty in this comparison; it does not remove every unknown influence."],["Kleine verschillen en overlappende marges rechtvaardigen geen stellige winnaar. Een eigen getal blijft ook in het individuele profiel beschikbaar.","Small differences and overlapping intervals do not establish a definite winner. Own values remain available in each driver’s profile.","Een klein verschil of overlappende onzekerheidsmarges is geen duidelijke overwinning. Bekijk ook het aantal gemeten races.","A small difference or overlapping uncertainty ranges is not a clear win. Also check how many races were measured."],["Ruwe loopbaanuitkomsten worden beïnvloed door auto, circuit, startpositie, reglement en gereden kansen. De gemeenschappelijke meetlat gebruikt alleen context die bij iedere gekozen rijder werkelijk aanwezig is. Dit kan een klein en niet representatief deel van de carrières zijn. Aantallen bepalen de precisie, niet automatisch de gewichten van de vergelijking.","Raw career results reflect car, circuit, origin position, regulations and opportunities. Common support uses only contexts actually observed for every selected driver. This may be a small, unrepresentative part of their careers. Counts determine precision, not automatically comparison weights.","Auto, startplek, regels en aantal races beïnvloeden loopbaancijfers. Voor een passende vergelijking gebruiken we alleen situaties die alle gekozen rijders hebben meegemaakt. Dat kan maar een klein deel van hun loopbaan zijn. Meer metingen maken de uitkomst meestal preciezer, maar geven die rijder niet automatisch extra gewicht.","Car, starting position, rules and race counts affect career figures. A matched comparison uses only situations experienced by all selected drivers. This may cover only a small part of their careers. More measurements usually improve precision but do not automatically give that driver more weight."],["Feitelijke totalen in de gekozen periode. Verschillende puntensystemen, carrièrelengtes en auto’s zijn hier niet gelijkgetrokken.","Factual totals in the selected period. Scoring systems, career lengths and cars are not standardized here.","Dit zijn de totalen in de gekozen periode. Houd rekening met verschillende puntensystemen, loopbaanlengtes en auto’s.","These are totals for the selected period. Bear in mind differences in scoring systems, career lengths and cars."],["Een netwerkmodel van kwalificatietijden binnen hetzelfde team en hetzelfde gemeten sessiesegment. Negatief log-tempo betekent sneller binnen het verbonden netwerk. Auto, specificatie, leeftijd, sessieverloop en tijdperk zijn hiermee niet volledig geïsoleerd.","A qualifying-time network within the same team and measured session segment. Negative log pace means faster within a connected network. Car specification, age, session conditions and era are not fully isolated.","We verbinden rijders via hun kwalificatietijden tegenover teamgenoten. Zo kunnen ook rijders uit verschillende jaren aan elkaar gekoppeld worden. Dat maakt auto’s, leeftijden en omstandigheden nog niet gelijk. Een lagere modelwaarde betekent sneller binnen dezelfde verbonden groep.","We link drivers through their qualifying times against teammates. This can connect drivers from different years. It does not make cars, ages or conditions equal. A lower model value means faster within the same connected group."],["Niet alle gekozen coureurs hebben voldoende gemeten paren in hetzelfde netwerkdeel. Er volgt geen onderlinge modelrangorde.","Not all selected drivers have enough measured pairs in the same component. No comparative model ranking is produced.","Deze rijders zijn niet allemaal met voldoende metingen aan elkaar verbonden. Daarom kunnen we ze met dit proefmodel niet onderling rangschikken.","These drivers are not all connected by enough measurements. This trial model therefore cannot rank them against each other."],["De foutverbetering tegenover nulverschil is positief in de racebloktoets. Dit controleert voorspelling van gemeten teamgenootverschillen, niet zuivere rijvaardigheid of een tijdperk-onafhankelijke GOAT-score.","Race-block evaluation supports improvement over zero gap. This checks prediction of measured teammate differences, not pure driver skill or an era-independent GOAT score.","In de test voorspelde het model teamgenootverschillen beter dan de aanname dat iedereen even snel is. Dat bewijst nog geen zuivere rijvaardigheid of betrouwbare ranglijst over tijdperken.","In testing, the model predicted teammate differences better than assuming equal pace. That still does not prove pure driver skill or a reliable ranking across eras."],["De onafhankelijke toets toont nog geen overtuigend onderbouwde verbetering tegenover een nulverschil. Modeluitkomsten blijven onderzoeksresultaten en worden geen algemene kwaliteitsranglijst.","Held-out testing does not yet establish a convincing improvement over a zero gap. Model outputs remain research results, not an overall skill ranking.","De test laat nog niet overtuigend zien dat dit model beter werkt dan gelijke snelheid aannemen. De uitkomsten zijn daarom voorlopig en vormen geen algemene ranglijst.","Testing has not convincingly shown that this model works better than assuming equal pace. Its results are therefore provisional and do not form an overall ranking."],["Dit netwerk gebruikt het volledige bewaarde tijdvak voor de verbindingen en wordt niet opnieuw getraind door het periodefilter bovenaan. Dat filter geldt voor de beschrijvende en gedeelde-contextanalyses.","This network uses the full retained period for its connections and is not retrained by the period filter above. That filter applies to descriptive and common-support analyses.","Dit proefmodel gebruikt alle beschikbare jaren. De periodekeuze bovenaan verandert het model niet; die geldt voor de andere vergelijkingen.","This trial model uses all available years. The period selector above does not change it; it applies to the other comparisons."],["Een afzonderlijk proefmodel voorspelt genormaliseerde eindklassering uit uitsluitend eerdere hoofdraces. De gewichten zijn gekozen op 2021–2023; 2024 en later blijven toetsraces. Geen kwalificatie, weer of resultaat van de te voorspellen race wordt als invoer gebruikt.","A separate trial model predicts normalized final classification from earlier main races only. Weights are selected on 2021–2023; 2024 onward remains held out. No qualifying, weather or outcome of the predicted race is used.","Dit proefmodel probeert de plaats in de uitslag te voorspellen met alleen informatie uit eerdere races. We stellen het af op 2021–2023 en testen het op races vanaf 2024. Het model krijgt vooraf geen kwalificatie, weer of uitslag van de te voorspellen race.","This trial model tries to predict finishing position using earlier races only. We tune it on 2021–2023 and test it on races from 2024 onward. It is not given the qualifying result, weather or outcome of the race being predicted."],["Het proefmodel verbetert de historische toets ten opzichte van zijn eenvoudige referentie. Er is nog geen afgeronde prospectieve toets.","The trial model improves held-out historical error over its simple baseline. A prospective evaluation is not complete.","Het model deed het beter dan de eenvoudige vergelijking in tests op al gereden races. Een afgeronde test op vooraf vastgelegde toekomstige races ontbreekt nog.","The model beat the simple comparison in tests on past races. A completed test on future races specified in advance is still missing."],["Het proefmodel heeft nog geen bruikbare verbetering aangetoond. Een ingewikkelder berekening wordt niet vanzelf een betere verwachting.","The trial model has not established a useful improvement. A more complicated computation is not automatically a better forecast.","Het model heeft nog geen bruikbare verbetering laten zien. Een ingewikkeldere berekening voorspelt dus niet vanzelf beter.","The model has not yet shown a useful improvement. A more complicated calculation does not automatically predict better."],["Er wordt daarom geen gevalideerde winstkans of algemene GOAT-score gepubliceerd. Een vooraf gedateerd onderzoeksscenario is apart opgeslagen zodat het later eerlijk getoetst kan worden.","No validated win probability or overall GOAT score is released. A dated prospective research scenario is stored separately for fair later evaluation.","Daarom tonen we nog geen betrouwbare winstkansen of algemeen GOAT-cijfer. Een vooraf opgeslagen voorspelling blijft bewaard om later eerlijk te kunnen testen.","We therefore do not yet show reliable win probabilities or an overall GOAT rating. A prediction saved in advance is retained for a fair later test."],["Onderzoek één eigenschap tegelijk. Feiten, gedeelde context en modellen zijn afzonderlijke stappen; er is geen onverklaard totaalrapportcijfer.","Investigate one trait at a time. Facts, common support and models are separate steps; there is no unexplained overall rating.","Vergelijk één eigenschap tegelijk. Bekijk eerst de cijfers en de omstandigheden. Er is geen totaalcijfer dat alle kwaliteiten tot één ranglijst samenvoegt.","Compare one trait at a time. Look at the figures and circumstances first. There is no overall number combining every quality into one ranking."],["De basis gebruikt breed beschikbare loopbaanfeiten. Voeg hieronder opgeslagen specialismen toe. Alleen coureurs met echte waarden voor alle aangevinkte parameters krijgen een PCA-positie; ontbrekende waarden worden nooit door nul of een gemiddelde vervangen.","The base uses widely available career facts. Add archived specialisms below. Only drivers with actual values for every checked feature receive a PCA position; missing values are never replaced with zero or an average.","Kies welke kenmerken de kaart gebruikt. Alleen rijders met gegevens voor al die kenmerken krijgen een plek in de grafiek. Een ontbrekend getal wordt niet ingevuld of als nul geteld.","Choose which traits the map uses. Only drivers with data for every chosen trait get a position in the chart. Missing numbers are neither filled in nor counted as zero."],["Er zijn minder dan drie complete profielen of minder dan twee variërende kenmerken. Kies minder of andere parameters. Er worden geen ontbrekende waarden ingevuld.","There are fewer than three complete profiles or fewer than two varying features. Choose fewer or different features. Missing values are not filled.","Er zijn te weinig rijders met alle gekozen gegevens, of de cijfers verschillen te weinig. Kies minder of andere kenmerken.","Too few drivers have all the chosen data, or their figures differ too little. Choose fewer or different traits."],["Deze coureurs blijven in het overzicht staan, maar de strook hieronder is geen PCA-as. Ook inschrijvingen zonder bevestigde racestart en uitsluitend gedeelde auto’s staan hier.","These drivers remain in the overview, but the strip below is not a PCA axis. It also contains entries without a confirmed race start and careers with only shared cars.","Deze rijders blijven zichtbaar, maar hebben te weinig geschikte gegevens voor een plek in de kaart. Hun stippen hieronder staan dus niet op een berekende as. Dit geldt ook bij onbevestigde starts of onduidelijke gedeelde auto’s.","These drivers remain visible but lack enough suitable data for a position on the map. Their dots below are not placed on a calculated axis. This also applies to unconfirmed starts or ambiguous shared cars."],["Een streep betekent onvoldoende gegevens, geen nul. De winstgrens is een verkennend modelresultaat; een niet gevonden grens is evenmin nul.","A dash means insufficient data, not zero. The gain boundary is an exploratory model result; a boundary not found is also not zero.","Een streep betekent dat het getal niet goed bepaald kan worden. Het is geen nul. Ook een niet gevonden winstgrens betekent niet dat de rijder nooit plaatsen wint.","A dash means the value cannot be established well enough. It is not zero. A missing gain boundary also does not mean the driver never gains places."],["Alle races van iedere coureur worden eerst samengenomen tot één loopbaanprofiel. Dicht bij elkaar betekent overeenkomst in de gekozen kenmerken. De assen zijn geen ranglijst van kwaliteit.","Each driver’s races are first pooled into a single career profile. Nearby points resemble each other in the chosen features. The axes are not a skill ranking.","Elke rijder krijgt één stip voor zijn hele loopbaan. Rijders dicht bij elkaar lijken op elkaar in de gekozen kenmerken. Verder naar rechts of hoger betekent niet beter. Niet alle verschillen passen in deze kaart.","Each driver gets one dot for their whole career. Nearby drivers resemble each other in the chosen traits. Farther right or higher does not mean better. Not every difference fits on this map."],["De vaste loopbaanperiode staat los van de periode en raceset bovenaan. Selectie geeft alleen kleur en labels; de punten en assen veranderen daardoor niet.","The fixed career period is independent of the period and race cohort above. Selection only adds colour and labels; it does not change points or axes.","De kaart gebruikt de volledige beschikbare loopbanen, los van de periodekeuze bovenaan. Andere rijders selecteren verandert alleen hun kleur en naamlabel.","The map uses full available careers, independently of the period selector above. Selecting other drivers changes only their colours and name labels."],["Grijs: overige coureurs. Teamkleur en label: geselecteerd, met team en nummer van de laatste geregistreerde race. Overlappende punten blijven op hun berekende positie staan.","Grey: other drivers. Team colour and label: selected, using the team and number of the last recorded race. Overlapping points retain their calculated positions.","Grijs: overige rijders. Teamkleur en naam: geselecteerde rijders, met het nummer en team van hun laatste geregistreerde race. Stippen die samenvallen blijven op hun echte plek.","Grey: other drivers. Team colour and name: selected drivers, using the number and team from their last recorded race. Overlapping dots stay in their actual positions."],["Mediane tijdwinst per race","Median time gained per race","Typische tijdwinst per race","Typical time gained per race"],["Mediane tijdwinst per cyclus","Median time gained per cycle","Typische tijdwinst per stopcyclus","Typical time gained per stop cycle"],["Mediane tijdwinst per kandidaatcyclus","Median time gained per candidate cycle","Typische tijdwinst per stopcyclus","Typical time gained per stop cycle"],["Mediane gemeten tijdwinst per kandidaatcyclus","Median measured time gained per candidate cycle","Typische tijdwinst per stopcyclus","Typical time gained per stop cycle"],["Mediaan van de racemedianen; iedere race telt eenmaal","Median of race medians; each race counts once","Eerst het midden per race, daarna het midden van die races","First the middle value per race, then the middle of those races"],["Gaussische voortschrijdende trend","Gaussian moving trend","Vloeiende lijn door het raceverloop","Smooth line through the race sequence"],["95%-bootstrapband · conditioneel","95% bootstrap band · conditional","Onzekerheid rond de lijn (95%)","Uncertainty around the line (95%)"],["PCA-parameters kiezen","Choose PCA features","Kenmerken voor de profielkaart","Choose traits for the profile map"],["Zonder onderbouwde PCA-positie","Without a supported PCA position","Te weinig gegevens voor de kaart","Too little data for the map"],["Overeenkomstige loopbaanprofielen","Similar career profiles","Welke loopbanen lijken op elkaar?","Which careers look alike?"],["Metronoom · vast veldpercentiel","Metronome · fixed field percentile","Metronoom · veldscore (0–100)","Metronome · field score (0–100)"],["Gecorrigeerde startscore","Adjusted start score","Score tegenover vergelijkbare starts","Score against matched starts"],["Gecorrigeerde startcurvebalans","Adjusted start curve balance","Vergelijkingswaarde van de startcurve","Start-curve comparison value"],["Gecorrigeerde racecurvebalans","Adjusted race curve balance","Vergelijkingswaarde van de racecurve","Race-curve comparison value"],["Winstgrens startcurve","Start curve gain boundary","Geschatte startplek voor positiewinst","Estimated grid position for gains"],["Winstgrens racevervolg","Race progression gain boundary","Geschatte beginpositie voor racewinst","Estimated starting position for race gains"],["Racescore · vergelijkbare finishes","Race score · comparable finishes","Racescore bij vergelijkbare finishes","Race score in matched finishes"],["Waargenomen","Observed","Gemeten resultaten","Measured results"],["Gedeelde context","Common support","Vergelijkbare situaties","Matched situations"],["Raceset","Race cohort","Welke races?","Which races?"],["Eigen carrièrekansen","Own career opportunities","Eigen races per rijder","Each driver’s own races"],["Parameters","Parameters","Kenmerken","Traits"],["Validatie","Validation","Controles","Checks"],["Toetsfout model","Held-out model error","Afwijking van het proefmodel","Trial model error"],["Toetsfout nulverschil","Held-out zero-gap error","Afwijking bij gelijke snelheid","Error when assuming equal pace"],["Races blijven onzekerheidsclusters","Races remain uncertainty clusters","Vergelijkingen uit dezelfde race horen bij elkaar","Comparisons from one race belong together"],["Log-tempo in %","Log pace in %","Tempo volgens het proefmodel","Pace according to the trial model"],["Conditionele 95%-marge","Conditional 95% interval","Onzekerheidsmarge (95%)","Uncertainty range (95%)"],["Genormaliseerde klassementspositie","Normalized classified position","Plaats in het veld, op een schaal van 0 tot 1","Position in the field, on a scale from 0 to 1"],["Waar strategie het verschil maakte","Where strategy made the difference","Wat er rond de pitstops veranderde","What changed around the pit stops"],["Robuuste tempotrend","Robust pace trend","Verloop van het rondetempo","Pattern in lap pace"],["Dekking en gedeelde definities","Coverage and shared definitions","Welke gegevens zijn beschikbaar?","Which data are available?"],["Bevestigde rijdende finishers","Confirmed on-track finishers","Rijders die rijdend de finish haalden","Drivers who were running at the finish"],["Interpretatie","Interpretation","Wat betekent dit?","What does this mean?"],["Uitleg bij de grafieken","Help with the charts","Uitleg bij de grafieken","Help with the charts"],["Mediane eigen rondetijdrang","Median own lap-time rank","Typische plaats van de rondetijd in het veld","Typical lap-time position in the field"],["Mediane pitwinst per tegenstandervergelijking","Median pit gain per opponent comparison","Typische pitwinst per vergelijking","Typical pit gain per comparison"],["Mediane kwalificatiepositie","Median qualifying position","Typische kwalificatiepositie","Typical qualifying position"],["Mediane afstand tot pole","Median gap to pole","Typische afstand tot pole","Typical gap to pole"],["Mediane kwalificatie","Median qualifying","Typische kwalificatiepositie","Typical qualifying position"],["Berekening, kenmerken en beperkingen","Calculation, features and limitations","Meer uitleg over de profielkaart","More about the profile map"],["Bronnen, versies en controlehashes","Sources, versions and verification hashes","Bronnen en bestandscontroles","Sources and file checks"],["Basissnelheid tegenover de teamgenoot op dezelfde raceronden, compound en vrijwel dezelfde bandenleeftijd. Voor beide rijders moet vrije lucht aantoonbaar zijn. Negatief betekent sneller.","Baseline pace against the teammate on the same race laps, compound and almost the same tyre age. Clear air must be evidenced for both drivers. Negative means faster.","Hoe snel reed deze rijder vergeleken met zijn teamgenoot, als beiden geen hinder van voorliggers hadden? We vergelijken dezelfde raceronden, hetzelfde bandentype en bijna even oude banden. Een negatief getal betekent sneller.","How fast was this driver compared with their teammate when neither was held up by traffic? We compare the same race laps, tyre type and almost the same tyre age. A negative number means faster."],["Rang van iedere volledige rondetijd in het gemeten veld, samengevoegd per circuit.","Rank of every complete lap time within the measured field, pooled by circuit.","We zetten de gemeten rondetijden naast die van de andere rijders in dezelfde raceronde. Plaats 1 is het snelst. Het overzicht per circuit vat die plaatsen samen.","We compare measured lap times with other drivers on the same race lap. Rank 1 is fastest. The circuit overview summarizes those ranks."],["Verandering van het tempovoordeel op de teamgenoot per tien ronden extra bandenleeftijd. Positief betekent beter tempobehoud. Alleen gelijke compounds, bijna gelijke leeftijd en een gemeten leeftijdsbereik van minstens tien ronden.","Change in pace advantage over the teammate per ten laps of additional tyre age. Positive means better pace retention. Same compounds, nearly equal ages and an observed age span of at least ten laps are required.","Behield deze rijder zijn tempo beter dan zijn teamgenoot terwijl de banden ouder werden? Het getal beschrijft de verandering over tien ronden. Positief is gunstiger. We vergelijken hetzelfde bandentype en bijna dezelfde bandenleeftijd.","Did this driver maintain pace better than their teammate as the tyres aged? The number describes the change over ten laps. Positive is better. We compare the same tyre type and almost the same tyre age."],["Extra rondetijd op nieuwe sets bij bandenleeftijd 1–3, tegenover de teruggetrokken eigen trendlijn uit leeftijd 4–10. Lager betekent minder vroeg tijdverlies. De outlap telt niet mee; dit is geen gemeten bandentemperatuur.","Extra lap time on new sets at tyre ages 1–3 compared with the backward extension of the own trend at ages 4–10. Lower means less early time loss. The out lap is excluded; this is not measured tyre temperature.","Hoeveel tijd verloor deze rijder in de eerste drie volledige ronden op nieuwe banden, vergeleken met het verwachte tempo op basis van latere ronden? Lager betekent minder vroeg tijdverlies. De ronde waarin hij de pits verlaat telt niet mee. Dit meet geen bandentemperatuur.","How much time did this driver lose in the first three full laps on new tyres, compared with expected pace based on later laps? Lower means less early time loss. The lap when the driver leaves the pits is excluded. This does not measure tyre temperature."],["Uitvoering in de twee volledige ronden vóór de inlap en de eerste twee volledige ronden na de outlap. Positief betekent sneller dan de eigen stinttrends verwachten. Pitstraatduur en de strategische beslissing worden niet beoordeeld.","Execution in the two full laps before the in lap and the first two full laps after the out lap. Positive means faster than expected from own stint trends. Pit-lane duration and the strategic decision are not assessed.","We bekijken het tempo in de twee volledige ronden vóór het binnenkomen en de eerste twee volledige ronden na het verlaten van de pits. Positief betekent sneller dan het eigen gebruikelijke tempo daar deed verwachten. De pitstopduur en de strategiekeuze zelf zitten niet in dit getal.","We examine pace in the two full laps before entering the pits and the first two full laps after leaving them. Positive means faster than expected from the driver’s usual pace around that stop. Pit-stop duration and the strategy decision itself are not measured by this number."],["De rondetijdrang hierboven zegt hoe snel de rijder was. Dit afzonderlijke getal zegt hoe herhaalbaar zijn eigen tempo was na aftrek van een geleidelijke stinttrend. Lager is regelmatiger; een constante rijder is niet automatisch snel.","The lap-time rank above describes speed. This separate metric describes how repeatable the driver’s own pace was after removing a gradual stint trend. Lower is more consistent; a consistent driver is not automatically fast.","Het vorige overzicht zegt hoe snel de ronden waren ten opzichte van het veld. Hier gaat het om hoe gelijkmatig de rijder zijn eigen tempo herhaalde, nadat een geleidelijke verandering tijdens een bandenreeks is verrekend. Lager betekent regelmatiger. Een regelmatige rijder is niet automatisch een snelle rijder.","The previous overview shows lap speed relative to the field. Here we look at how steadily the driver repeated their own pace, after accounting for gradual change during a tyre stint. Lower means more consistent. A consistent driver is not automatically a fast driver."],["Dit zijn de kwalificatieresultaten, niet de uiteindelijke startopstelling. Strafplaatsen, pitlanestarts, historische sessieformats en sprintkwalificaties kunnen daarvan afwijken. Ontbrekende segmenttijden worden niet uit de grid afgeleid. Q1/Q2/Q3 zijn alleen beschikbaar waar de bron die segmenten registreert; losse historische sessies zijn geen moderne knock-outronden. Een gridverschil bewijst niet automatisch een straf.","These are qualifying results, not the final starting grid. Grid penalties, pit-lane starts, historical formats and sprint qualifying may differ. Missing segment times are not inferred from grid position. Q1/Q2/Q3 appear only where recorded; separate historical sessions are not modern knockout rounds. A grid difference does not automatically prove a penalty.","Dit zijn de uitslagen van de kwalificatie. Door straffen of starts uit de pitstraat kan de uiteindelijke startplek anders zijn. Oudere kwalificaties werkten soms anders. Een ontbrekende tijd wordt niet uit de startplek afgeleid; geschatte tijden zijn apart herkenbaar.","These are qualifying results. Penalties or pit-lane starts may change the actual grid position. Older qualifying formats could differ. Missing times are not inferred from grid position; estimated times are marked separately."],["Uitval, verantwoordelijkheid en straf zijn verschillende feiten. De telling gebruikt de uitslag en expliciete uitvalredenen; een ontbrekende oude DNF-vlag betekent geen nul. Een geklasseerde rijder kan vóór de finish gestopt zijn. Alleen “niet geklasseerd” bewijst geen uitval. Een botsing of zelfstandige crash bewijst geen eigen schuld. Besluiten voor een andere betrokken rijder en boetes voor een renstal gelden niet als persoonlijke straffen. Het besluitenarchief en de beoordeling van verantwoordelijkheid zijn onvolledig: geen gevonden record betekent onbekend, niet nul. Oproepen, herzieningen en vervangen of herroepen besluiten tellen niet als nieuwe straffen.","Retirement, responsibility and sanction are different facts. Counts use results and explicit retirement reasons; a missing old DNF flag does not mean zero. A classified driver may have stopped before the finish. “Not classified” alone does not establish retirement. A collision or solo crash does not establish fault. Sanctions against another involved driver and competitor fines are not personal driver penalties. The ruling archive and responsibility reviews are incomplete: no record means unknown, not zero. Summons, reviews and superseded or overturned rulings are not counted as new penalties.","Uitval, schuld en straf zijn verschillende dingen. We gebruiken de uitslag en de vermelde uitvalreden. Een rijder kan nog in de uitslag staan terwijl hij vóór de finish is gestopt. Een ongeluk bewijst op zichzelf geen eigen schuld. Alleen een gevonden en gelezen besluit kan daar duidelijkheid over geven; ontbrekende informatie blijft onbekend.","Retirement, fault and penalties are different things. We use the result and recorded retirement reason. A driver may still appear in the classification after stopping before the finish. An accident alone does not prove fault. Only a located and reviewed ruling can clarify responsibility; missing information remains unknown."],["De parameterlijst telt de bewaarde genormaliseerde racegegevens, coureursanalyses, bronregisters en brondatabasetabellen. PDF’s, afbeeldingen, onbewerkte timingstreams en binaire caches staan bij de bestandstelling; hun volledige tekst of pixels zijn geen extra statistische datapunten. Grote originele archieven blijven buiten de interactieve pagina’s.","The parameter list counts retained normalized race data, driver analyses, source registers and source database tables. PDFs, images, raw timing streams and binary caches appear in the file census; their full text or pixels are not extra statistical data points. Large original archives stay outside the interactive pages.","Deze lijst telt de gegevens die we hebben opgeslagen: verwerkte racegegevens, coureurscijfers en de bijbehorende bronnen. PDF’s, afbeeldingen en originele bestanden staan apart in het bestandenoverzicht. De tekst en pixels daarvan tellen niet als extra racegegevens.","This list counts stored information: processed race data, driver figures and their sources. PDFs, images and original files are listed separately. Their text and pixels do not count as extra race measurements."],["Een rang is afgeleid uit gemeten rondetijden op hetzelfde rondenummer. Een modelcurve, bootstrapinterval of afgeleide pitstopcyclus is geen extra gemeten ronde. Voor 1996 worden losse snelste-rondemetingen niet gebruikt als volledige reeks: een gebruikte reeks heeft minstens vijf tijden en minstens de helft van de bekende rondeposities voor die coureur.","Ranks are derived from measured lap times on the same numbered lap. Model curves, bootstrap intervals and inferred pit cycles are not extra measured laps. Before 1996, isolated fastest-lap measurements are not complete series: a used run requires at least five times and half the known lap positions for that driver.","Een rondetijdplaats komt uit de gemeten tijden op dezelfde raceronde. Een berekende lijn of onzekerheidsmarge is geen extra gemeten ronde. Voor jaren vóór 1996 gebruiken we alleen een tijdreeks als er minstens vijf tijden zijn en tijden beschikbaar zijn voor minstens de helft van de bekende rondeposities van die rijder.","A lap-time rank comes from measured times on the same race lap. A calculated line or uncertainty range is not an extra measured lap. Before 1996, a time series is used only if it contains at least five times and covers at least half of the driver’s known lap positions."]],maps={nl:new Map(),en:new Map()};
for(const [oldNl,oldEn,nl,en]of catalog)for(const key of [oldNl,oldEn,nl,en]){maps.nl.set(key.trim(),nl);maps.en.set(key.trim(),en);}
const fragments=Object.fromEntries(['nl','en'].map(lang=>[lang,[...maps[lang]].filter(([key,value])=>key.length>=18&&key!==value).sort((a,b)=>b[0].length-a[0].length)]));
const words={nl:[[/95%-bootstrap(?:interval|band)/giu,'Onzekerheidsmarge (95%)'],[/\bPCA-punten\b/g,'stippen in de kaart'],[/\bPC1\b/g,'As 1'],[/\bPC2\b/g,'As 2'],[/\bwaarnemingen\b/giu,'metingen'],[/\bdatapunten\b/giu,'meetpunten'],[/\bmodelband\b/giu,'onzekerheid rond de lijn'],[/\bmedianen\b/giu,'middelste waarden'],[/\bmediaan\b/giu,'middelste waarde'],[/\bmediane\b/giu,'typische'],[/\bkwartielen\b/giu,'middelste helft'],[/\bcompounds\b/giu,'bandentypen'],[/\bcompound\b/giu,'bandentype']],en:[[/95% bootstrap (?:interval|band)/giu,'Uncertainty range (95%)'],[/\bPCA points\b/g,'dots on the map'],[/\bPC1\b/g,'Axis 1'],[/\bPC2\b/g,'Axis 2'],[/\bobservations\b/giu,'measurements'],[/\bmedians\b/giu,'middle values'],[/\bmedian\b/giu,'middle value'],[/\bquartiles\b/giu,'middle half'],[/\bcompounds\b/giu,'tyre types'],[/\bcompound\b/giu,'tyre type']]};
function text(value,language='nl'){if(typeof value!=='string'||!value.trim())return value;const lang=language==='en'?'en':'nl',trim=value.trim(),mapped=maps[lang].get(trim);if(mapped!==undefined)return value.slice(0,value.indexOf(trim))+mapped+value.slice(value.indexOf(trim)+trim.length);let result=value;if(value.length>=18)for(const[key,replacement]of fragments[lang])if(result.includes(key))result=result.split(key).join(replacement);for(const[pattern,replacement]of words[lang])result=result.replace(pattern,replacement);return result;}
const technicalSections=new WeakSet();
function technical(node){const el=node?.nodeType===3?node.parentElement:node;if(!el?.closest)return true;if(el.closest('script,style,pre,code,blockquote,[data-technical-copy],[data-language-toggle],#driver-incidents table,.quality-method,.starter-research-method,.starter-method'))return true;const details=el.closest('details');if(details){const summary=details.querySelector(':scope > summary')?.textContent||'';if(/bereken|reken|method|model,|bron|source|calculation|verification|beperkingen|limitations|onderbouwing/i.test(summary))technicalSections.add(details);if(!el.closest('summary')&&technicalSections.has(details))return true;}return false;}

const api={text,technical,lookup:(value,lang='nl')=>maps[lang==='en'?'en':'nl'].get(String(value).trim()),version:1,rules:catalog.length};window.readableCopy=api;
if(typeof document==='undefined')return;
const exempt=/uitleg[^/]*\.html$|bronnen-en-methode\.html$|stijlgids\.html$|goat-backup-/.test(location.pathname);if(exempt)return;
let busy=false,scheduled=false,full=true;const pending=new Set();const observer=new MutationObserver(records=>{for(const r of records){if(r.type==='attributes'&&r.attributeName==='lang'){full=true;continue;}if(r.type==='childList'){for(const node of r.addedNodes)pending.add(node);}else pending.add(r.target);}if(!scheduled){scheduled=true;requestAnimationFrame(apply);}});
function observe(){if(window.siteLanguage)return;observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['lang','title','aria-label','placeholder']});}
function apply(){scheduled=false;if(busy)return;busy=true;observer.disconnect();try{const lang=document.documentElement.lang==='en'?'en':'nl';if(window.siteLanguage){window.siteLanguage.set(window.siteLanguage.language);return;}const roots=full?[document.body]:[...pending].filter(node=>node.isConnected);full=false;pending.clear();
function rewrite(node){if(technical(node))return;const next=text(node.nodeValue,lang);if(next!==node.nodeValue)node.nodeValue=next;}
for(const root of roots){if(root.nodeType===3){rewrite(root);continue;}if(root.nodeType!==1)continue;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())rewrite(node);const elements=[root,...root.querySelectorAll('[title],[aria-label],[placeholder]')];for(const el of elements){if(technical(el))continue;for(const key of ['title','aria-label','placeholder'])if(el.hasAttribute(key)){const before=el.getAttribute(key),after=text(before,lang);if(before!==after)el.setAttribute(key,after);}}}}finally{busy=false;observe();}}
api.apply=apply;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});else apply();
})();
